(function(){
  const KEY='daymark-wellbeing-v1';
  const sessions=[
    {id:'morning',number:'01',tone:'sunrise',kind:'НА ПОЧАТОК ДНЯ',title:'Налаштуватися на день',duration:'3 хв',summary:'Спокійно зібрати увагу, обрати свій темп і почати без поспіху.',phrase:'Я можу прожити цей день у своєму темпі.',steps:[
      {kind:'СЛУХАЙ',title:'Влаштуйся зручно',text:'Сядь або стань так, як тобі комфортно. Відчуй опору під собою. Зроби спокійний вдих і повільний видих.'},
      {kind:'ПОВТОРИ ЗА МОЇМ ГОЛОСОМ',title:'Твоя фраза на сьогодні',text:'Я можу прожити цей день у своєму темпі.'},
      {kind:'СЛУХАЙ',title:'Обери напрямок',text:'Подумай про одну справу або відчуття, якому хочеш дати місце сьогодні. Одного наміру достатньо.'},
      {kind:'ПОВТОРИ ЗА МОЇМ ГОЛОСОМ',title:'Завершальна фраза',text:'Мені достатньо зробити наступний крок.'}
    ]},
    {id:'after-day',number:'02',tone:'sunset',kind:'ПІСЛЯ ВАЖКОГО ДНЯ',title:'Видихнути й відпустити день',duration:'4 хв',summary:'Зупинитися, послабити напругу й не вимагати від себе вирішити все зараз.',phrase:'Я зробила достатньо на сьогодні. Тепер можна відпочити.',steps:[
      {kind:'СЛУХАЙ',title:'Залиш день позаду',text:'Знайди зручне місце. М’яко розтисни щелепу й опусти плечі, якщо це приємно. Зараз не потрібно нічого доводити.'},
      {kind:'ПОВТОРИ ЗА МОЇМ ГОЛОСОМ',title:'Скажи собі це',text:'Я зробила достатньо на сьогодні. Тепер можна відпочити.'},
      {kind:'СЛУХАЙ',title:'Дай собі паузу',text:'Зроби повільний видих. Не потрібно оцінювати цей день або негайно його виправляти.'},
      {kind:'ПОВТОРИ ЗА МОЇМ ГОЛОСОМ',title:'На завершення',text:'Один важкий день не визначає мене і не скасовує мій шлях.'}
    ]},
    {id:'hard-time',number:'03',tone:'believe',kind:'КОЛИ ЗАРАЗ СКЛАДНО',title:'Підтримати себе й повірити у власні сили',duration:'5 хв',summary:'Побути поруч із собою в непростий період і згадати: можна рухатися малими кроками.',phrase:'Я можу пройти цей період крок за кроком.',steps:[
      {kind:'СЛУХАЙ',title:'Побудь у цій миті',text:'Зроби комфортний вдих і видих. Не потрібно бачити весь шлях наперед — побудь лише в цій хвилині.'},
      {kind:'ПОВТОРИ ЗА МОЇМ ГОЛОСОМ',title:'Повтори у своєму темпі',text:'Я можу пройти цей період крок за кроком.'},
      {kind:'СЛУХАЙ',title:'Згадай свою опору',text:'Пригадай, що вже допомагало тобі раніше: людина, маленька дія або твоя власна наполегливість.'},
      {kind:'ПОВТОРИ ЗА МОЇМ ГОЛОСОМ',title:'Тобі не треба бути ідеальною',text:'Я можу попросити про підтримку. Мій наступний крок має значення.'}
    ]}
  ];
  function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}');}catch{return{};}}
  let data=read(),selected=null,step=-1,complete=false;
  if(!data.sessions||typeof data.sessions!=='object')data.sessions={};
  function save(){try{localStorage.setItem(KEY,JSON.stringify(data));}catch{}}
  function escText(s){return typeof esc==='function'?esc(s):String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function doneToday(){return data.sessions[selectedDate]||[];}
  function sessionCard(s){const done=doneToday().includes(s.id);return '<article class="voice-session-card '+s.tone+'"><div class="voice-card-meta"><span>'+s.number+' / '+s.kind+'</span><span>'+s.duration+'</span></div><h3>'+s.title+'</h3><p>'+s.summary+'</p><div class="voice-quote"><small>ФРАЗА, ЯКУ ПОВТОРИМО</small><b>“'+s.phrase+'”</b></div><button class="voice-card-cta" data-action="wellbeing-open" data-id="'+s.id+'">'+(done?'Пройти ще раз':'Переглянути сеанс')+' <span>↗</span></button>'+(done?'<small class="voice-done">✓ Уже пройдено сьогодні</small>':'')+'</article>';}
  function selectedSession(){return sessions.find(s=>s.id===selected);}
  function player(){if(!selected)return '';const s=selectedSession();let body='';if(complete){body='<div class="voice-complete"><span>✓</span><b>Сеанс завершено</b><p>Дякую, що побула з собою. Можеш повернутися до цієї практики будь-коли.</p><button data-action="wellbeing-restart">Пройти ще раз</button></div>';}else if(step<0){body='<p class="voice-start-copy">Знайди кілька вільних хвилин. Прочитай сценарій неквапливо: у справжньому записі тут звучатиме мій голос, а після фраз будуть паузи, щоб повторити за мною.</p><div class="voice-first-phrase"><small>ФРАЗА, ЯКУ ТИ ПОВТОРИШ</small><b>“'+s.phrase+'”</b></div><button class="voice-primary" data-action="wellbeing-begin">Почати текстове демо <span>→</span></button>';}else{const item=s.steps[step];body='<div class="voice-progress"><span>КРОК '+(step+1)+' З '+s.steps.length+'</span><i><b style="width:'+((step+1)/s.steps.length*100)+'%"></b></i></div><div class="voice-step '+(item.kind.includes('ПОВТОРИ')?'repeat':'listen')+'"><small>'+(item.kind.includes('ПОВТОРИ')?'◉ ':'◌ ')+item.kind+'</small><h3>'+item.title+'</h3><p>“'+item.text+'”</p></div><button class="voice-primary" data-action="wellbeing-next">'+(item.kind.includes('ПОВТОРИ')?'Я повторила — далі':'Продовжити')+' <span>→</span></button><p class="voice-demohint">Це текстовий демосценарій — голосового запису тут поки немає.</p>';}return '<section class="voice-player" id="voicePlayer"><div class="voice-player-head"><div><span class="voice-eyebrow">'+s.kind+' · '+s.duration+'</span><h2>'+s.title+'</h2></div><button class="voice-close" data-action="wellbeing-close" aria-label="Закрити сеанс">×</button></div><div class="voice-audio-status"><span class="voice-wave" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></span><span><b>Запис моїм голосом</b><small>З’явиться після запису аудіо</small></span><em>АУДІО / СКОРО</em></div>'+body+'</section>';}
  function motivation(){return '<section class="voice-motivation"><div class="voice-motivation-head"><span class="voice-eyebrow">НАВІЩО ЦІ МЕДИТАЦІЇ</span><h2>Щоб заспокоїтися.<br><em>Щоб налаштуватися й знову повірити в себе.</em></h2><p>Це твій час почути мій голос, відчути підтримку й повторити слова, яких інколи так бракує. Обери сеанс під свій стан.</p></div><div class="voice-benefits"><article><span>☀</span><small>ПЕРЕД ПОЧАТКОМ ДНЯ</small><h3>Позитивний настрій на день</h3><p>Замість ранкової метушні — три хвилини, щоб налаштуватися, зібратися з думками й почати день із вірою у свої сили.</p><button data-action="wellbeing-open" data-id="morning">Відкрити ранковий сеанс ↗</button></article><article><span>☾</span><small>ПІСЛЯ ВАЖКОГО ДНЯ</small><h3>Заспокоїтися й відпустити напругу</h3><p>Послухай спокійний голос, видихни й повтори слова, які допоможуть завершити важкий день без самокритики.</p><button data-action="wellbeing-open" data-id="after-day">Відкрити вечірній сеанс ↗</button></article><article><span>🤍</span><small>У СКЛАДНИЙ ПЕРІОД</small><h3>Почути підтримку й повірити в себе</h3><p>Коли здається, що нічого не вийде, слухай слова підтримки й повторюй за мною: «Я можу пройти цей період крок за кроком».</p><button data-action="wellbeing-open" data-id="hard-time">Відкрити сеанс підтримки ↗</button></article></div><p class="voice-motivation-foot">Не потрібно чекати особливого моменту — обирай сеанс тоді, коли тобі потрібні спокій, настрій або підтримка.</p></section>';}
  function view(){const done=doneToday().length;return '<div class="well-page"><section class="voice-hero"><div class="voice-hero-copy"><span class="voice-eyebrow">DAYMARK · МЕДИТАЦІЇ ТА АФІРМАЦІЇ</span><h1>Заспокоїтись.<br>Налаштуватись на день.<br><em>Знову повірити в себе.</em></h1><p>Медитації та афірмації моїм голосом, щоб заспокоїтися, вирівняти емоційний стан і отримати позитивний настрій. Слухай та повторюй слова підтримки й віри в себе. У макеті поки показані тексти сеансів.</p><div class="voice-tags"><span>Налаштуватися на день</span><span>Видихнути після важкого</span><span>Підтримати себе у складний період</span></div></div><div class="voice-art" aria-hidden="true"><div class="voice-disc"><span>♪</span></div><div class="voice-spark spark-one">🎧</div><div class="voice-spark spark-two">♡</div><span class="voice-art-label">СЛУХАЙ<br>·<br>ПОВТОРЮЙ</span></div><div class="voice-cutout">КІЛЬКА ХВИЛИН — ТІЛЬКИ ДЛЯ ТЕБЕ</div></section><section class="voice-how"><div class="voice-how-title"><span class="voice-eyebrow">ЦЕ ДУЖЕ ПРОСТО</span><h2>Ти слухаєш. Я говорю. Ти повторюєш.</h2></div><div class="voice-how-steps"><div><span>01</span><b>Обери, що тобі потрібно</b></div><div><span>02</span><b>Слухай мій голос</b></div><div><span>03</span><b>Повторюй фрази за мною</b></div></div><p class="voice-how-note">Можна повторювати вголос або подумки. Якщо фраза не відгукується — пропусти її.</p></section>'+motivation()+'<section class="voice-library"><div class="voice-library-head"><div><span class="voice-eyebrow">ОБЕРИ СВОЮ СИТУАЦІЮ</span><h2>Що тобі потрібно зараз?</h2><p>У кожному сеансі є коротка медитація і фрази, які ти повторюєш за голосом.</p></div><span class="voice-counter">'+done+' з '+sessions.length+'<small>сеансів сьогодні</small></span></div><div class="voice-session-grid">'+sessions.map(sessionCard).join('')+'</div></section>'+player()+'<section class="voice-note"><span>♪</span><div><b>Поки це демоверсія</b><p>Текст практик уже можна переглянути й пройти крок за кроком. Коли ти запишеш аудіо, замінимо демо на справжні сеанси твоїм голосом.</p></div><small>ТЕКСТОВЕ ДЕМО<br>АУДІО ДОДАМО</small></section><p class="voice-safety">Ці практики — простір для паузи й самопідтримки, не психотерапія і не заміна фахової допомоги.</p></div>';}
  function open(id){selected=id;step=-1;complete=false;render();setTimeout(()=>document.getElementById('voicePlayer')?.scrollIntoView({behavior:'smooth',block:'center'}),80);}
  function close(){selected=null;step=-1;complete=false;render();}
  function begin(){step=0;complete=false;render();document.getElementById('voicePlayer')?.scrollIntoView({behavior:'smooth',block:'center'});}
  function next(){const s=selectedSession();if(step<s.steps.length-1){step++;render();document.getElementById('voicePlayer')?.scrollIntoView({behavior:'smooth',block:'center'});return;}const list=doneToday();if(!list.includes(s.id))list.push(s.id);data.sessions[selectedDate]=list;save();complete=true;step=-1;render();document.getElementById('voicePlayer')?.scrollIntoView({behavior:'smooth',block:'center'});}
  function restart(){step=0;complete=false;render();document.getElementById('voicePlayer')?.scrollIntoView({behavior:'smooth',block:'center'});}
  function go(){navigate('wellbeing');}
  window.daymarkWellbeingView=view;window.daymarkOpenWellbeing=go;
  VIEW_NAMES.wellbeing='Медитації';I.audio='<path d="M4 10v4m4-7v10m4-13v16m4-13v10m4-7v4"/>';
  const oldNav=navHTML;navHTML=function(bottom=false){const html=oldNav(bottom);return bottom?html:html+'<button class="nav-item '+(currentView==='wellbeing'?'active':'')+'" data-view="wellbeing">'+icon('audio')+'<span>Медитації</span></button>';};
  appNav=function(){return [['today','Сьогодні'],['journey','Мій шлях'],['photo','Сфоткай'],['recipes','Ідеї їжі'],['food','Щоденник']].map(([v,n])=>v==='photo'?'<button class="nav-item camera-nav" data-action="photo"><span>'+icon('camera')+'</span><b>'+n+'</b></button>':'<button class="nav-item '+(currentView===v?'active':'')+'" data-view="'+v+'">'+icon(v)+'<span>'+n+'</span></button>').join('');};
  const oldHome=homeApp;homeApp=function(){return oldHome().replace('<div class="home-quick-heading">','<button class="voice-home-card" data-view="wellbeing"><span class="voice-home-icon">♪</span><span><small>МЕДИТАЦІЇ ТА АФІРМАЦІЇ</small><b>Заспокойся. Налаштуйся. Повір у себе.</b><em>Для ранку, важкого дня або складного періоду</em></span><i>↗</i></button><div class="home-quick-heading">');};
  actions.wellbeing=go;actions['wellbeing-open']=b=>open(b.dataset.id);actions['wellbeing-close']=close;actions['wellbeing-begin']=begin;actions['wellbeing-next']=next;actions['wellbeing-restart']=restart;
  const oldRender=render;render=function(){oldRender();document.body.classList.toggle('wellbeing-view',currentView==='wellbeing');if(currentView==='wellbeing')$('view').innerHTML=view();};render();
})();
